-- First Harley-Davidson sourced model research batch, exact catalogue identities.
-- Original model history, model years, and limited editions are scoped separately.
-- Publish only where exact model exists in approved clean catalogue.
with documented(catalog_model_id,category,label,value,start_year,source_name,source_url,scope_note) as (values
(127,'history','Fat Boy original 1990 factory launch and Evolution engine','{"launch_year":1990,"original_factory_colour":"Fine Silver Metallic","original_engine":"Rigid-mounted Evolution V-twin","generation_scope":"Original 1990 Fat Boy, not modern Milwaukee-Eight versions"}'::jsonb,1990,'Harley-Davidson 2025 Fat Boy Gray Ghost factory retrospective','https://www.harley-davidson.com/us/en/motorcycles/2025/fat-boy-gray-ghost.html','Historical 1990 original model; do not attribute its engine to later versions.'),
(127,'specification','Fat Boy 2025 UK factory engine and output','{"model_year":2025,"engine":"Milwaukee-Eight 117 Custom V-twin","engine_capacity_cc":1923,"power":"103 hp","torque":"168 Nm","market":"UK 2025 factory specification"}'::jsonb,2025,'Harley-Davidson UK — 2025 Fat Boy specifications','https://www.harley-davidson.com/gb/en/motorcycles/2025/fat-boy.html','2025 UK model; 2026/ealier generations have separate factory specifications.'),
(127,'model_year','Fat Boy Gray Ghost 2025 Icons tribute limited edition','{"model_year":2025,"edition":"Fat Boy Gray Ghost","numbered_edition":"1,990 examples","heritage_reference":"Original 1990 Fat Boy","note":"Gray Ghost is a specific Icons special edition, not the specification of every 2025 Fat Boy"}'::jsonb,2025,'Harley-Davidson Europe — Icons motorcycle collection','https://www.harley-davidson.com/eu/en/motorcycles/icons.html','Exactly 2025 Fat Boy Gray Ghost edition, not generic Fat Boy equipment.'),
(115,'engine','Breakout 2025 UK Milwaukee-Eight 117 Custom','{"model_year":2025,"engine":"Milwaukee-Eight 117 Custom V-twin","power":"103 hp","torque":"168 Nm","market":"UK 2025 manufacturer listing"}'::jsonb,2025,'Harley-Davidson UK — 2025 Breakout','https://www.harley-davidson.com/gb/en/motorcycles/2025/breakout.html','2025 UK Breakout only; do not apply to previous years.'),
(115,'chassis','Breakout 2025 chopper-style factory chassis','{"model_year":2025,"front_wheel":"21-inch","rear_tyre":"240 mm","rake":"34 degrees","styling":"Bobtail rear fender and long rake"}'::jsonb,2025,'Harley-Davidson UK — 2025 Breakout design','https://www.harley-davidson.com/gb/en/motorcycles/2025/breakout.html','UK 2025 marketing dimensions, not historic Breakout years.'),
(868,'engine','Heritage Classic 2025 manufacturer engine and performance','{"model_year":2025,"engine":"Milwaukee-Eight 117 Classic","engine_capacity_cc":1923,"power":"91 hp","torque":"156 Nm","market":"UK 2025 factory specification"}'::jsonb,2025,'Harley-Davidson UK — Heritage Classic 2025','https://www.harley-davidson.com/gb/en/motorcycles/2025/heritage-classic.html','UK 2025 factory configuration; do not assume every Heritage Classic year has 117 engine.'),
(868,'touring','Heritage Classic 2025 removable touring equipment','{"model_year":2025,"windshield":"Detachable two-tone windshield","luggage":"Lockable, weather-resistant saddlebags","equipment":"2025 factory reference, not a universal equipment promise"}'::jsonb,2025,'Harley-Davidson UK — Heritage Classic 2025 touring design','https://www.harley-davidson.com/gb/en/motorcycles/2025/heritage-classic.html','Equipment referenced for 2025 UK; inspect any actual motorcycle for fitted accessories.'),
(153,'market_launch','Sportster S joined Harley Sportster family in 2021','{"introduction_year":2021,"powertrain":"Revolution Max 1250T liquid-cooled V-twin","history":"New-generation Sportster S replaced the traditional air-cooled Sportster powertrain approach"}'::jsonb,2021,'Harley-Davidson — Sportster history','https://www.harley-davidson.com/us/en/content/expert-advice/harley-davidson-sportster-history.html','Original 2021 introduction, not 2025 or 2026 technical figures.'),
(153,'performance','Sportster S 2025 UK manufacturer performance','{"model_year":2025,"engine":"Revolution Max 1250T","power":"121 hp (90 kW)","torque":"125 Nm","market":"United Kingdom 2025 specification"}'::jsonb,2025,'Harley-Davidson UK — 2025 Sportster S','https://www.harley-davidson.com/gb/en/motorcycles/2025/sportster-s.html','Manufacturer 2025 UK model only; not all historic Sportster models.'),
(140,'market_launch','Nightster Revolution Max 975T introduced in 2022','{"introduction_year":2022,"engine":"Liquid-cooled Revolution Max 975T V-twin","family":"Modern Sportster generation","variant":"Nightster, not Nightster Special"}'::jsonb,2022,'Harley-Davidson — Sportster family history','https://www.harley-davidson.com/us/en/content/expert-advice/harley-davidson-sportster-history.html','Introduction of base Nightster; do not mix with Special trim.'),
(140,'specification','Nightster 2026 UK model-year specification','{"model_year":2026,"engine":"Revolution Max 975T","power":"89 hp","market":"United Kingdom","feature":"Selectable ride modes and LED lighting"}'::jsonb,2026,'Harley-Davidson UK — 2026 Nightster','https://www.harley-davidson.com/gb/en/motorcycles/nightster.html','2026 base Nightster; avoid using Nightster Special US power figure.'),
(431,'market_launch','Pan America 1250 adventure family launched February 2021','{"launch_month":"2021-02","models":["Pan America 1250","Pan America 1250 Special"],"positioning":"Harley-Davidson first modern adventure touring motorcycle platform","scope_note":"Manufacturer announced sales performance of the Special in North America, not the standard 1250"}'::jsonb,2021,'Harley-Davidson Investor Relations — Pan America 2021 launch','https://investor.harley-davidson.com/news/news-details/2021/Harley-Davidson-Pan-America-1250-Special-Becomes-The-1-Selling-Adventure-Touring-Motorcycle-In-North-America/default.aspx','Manufacturer confirms the February 2021 introduction of base and Special; ranking applies Special only.'),
(157,'engineering','Street Glide 2026 Milwaukee-Eight 117 and infotainment','{"model_year":2026,"engine":"Milwaukee-Eight 117","infotainment":"312 mm Skyline OS display","aerodynamics":"Batwing fairing modernisation","market":"United Kingdom manufacturer 2026 reference"}'::jsonb,2026,'Harley-Davidson UK — 2026 Street Glide','https://www.harley-davidson.com/gb/en/motorcycles/street-glide.html','2026 Street Glide only; do not apply to pre-2024 fairing or engine.'),
(143,'engineering','Road Glide 2026 Milwaukee-Eight 117 and Skyline OS','{"model_year":2026,"engine":"Milwaukee-Eight 117","infotainment":"312 mm Skyline OS","design":"Updated Sharknose touring fairing","market":"UK 2026 manufacturer Road/Street Glide comparison"}'::jsonb,2026,'Harley-Davidson UK — 2026 Street Glide and Road Glide overview','https://www.harley-davidson.com/gb/en/motorcycles/street-glide.html','Official 2026 comparison names both touring motorcycles; record scoped to Road Glide.'),
(125,'model_year','2021 Electra Glide Revival limited Icons edition','{"model_year":2021,"edition":"Electra Glide Revival","numbered_edition":"1,500 examples","historical_reference":"1969 Electra Glide","engine":"Milwaukee-Eight 114","infotainment":"Boom! Box GTS 6.5 with Apple CarPlay","note":"Named special-edition Revival, not ordinary Electra Glide production"}'::jsonb,2021,'Harley-Davidson Europe — Icons Motorcycle Collection','https://www.harley-davidson.com/eu/en/motorcycles/icons.html','2021 Electra Glide Revival specific edition, distinct from generic Electra Glide range.')
)
insert into public.motorcycle_catalog_facts(catalog_model_id,category,label,value,start_year,source_name,source_url,market,verification_status)
select d.catalog_model_id,d.category,d.label,d.value,d.start_year,d.source_name,d.source_url,'Manufacturer-documented year and market','verified' from documented d
where exists (select 1 from public.motorcycle_catalog_dropdown_clean c where c.model_id=d.catalog_model_id)
and not exists(select 1 from public.motorcycle_catalog_facts f where f.catalog_model_id=d.catalog_model_id and f.label=d.label and f.source_url=d.source_url);

with documented(catalog_model_id,label,source_name,source_url,scope_note) as (values
